import{_ as t,c as o,o as a,ae as i}from"./chunks/framework.CFeneB-q.js";const h=JSON.parse('{"title":"E9 前端开发指南 · 需求缺口与不足分析","description":"","frontmatter":{},"headers":[],"relativePath":"requirements-gap-analysis.md","filePath":"requirements-gap-analysis.md","lastUpdated":1789438865000}'),l={name:"requirements-gap-analysis.md"};function r(n,e,s,d,c,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="e9-前端开发指南-·-需求缺口与不足分析" tabindex="-1">E9 前端开发指南 · 需求缺口与不足分析 <a class="header-anchor" href="#e9-前端开发指南-·-需求缺口与不足分析" aria-label="Permalink to &quot;E9 前端开发指南 · 需求缺口与不足分析&quot;">​</a></h1><blockquote><p>配套 <a href="./dev-guide-requirements.html">需求文档</a>。本文分析原始需求「三端 × 七板块」中的漏洞与不足，每条按 <strong>问题 / 影响 / 建议</strong> 三要素展开。结论摘要见文末。</p></blockquote><h2 id="一、内容类缺口" tabindex="-1">一、内容类缺口 <a class="header-anchor" href="#一、内容类缺口" aria-label="Permalink to &quot;一、内容类缺口&quot;">​</a></h2><h3 id="_1-1-pc-端缺「入门」总览页" tabindex="-1">1.1 PC 端缺「入门」总览页 <a class="header-anchor" href="#_1-1-pc-端缺「入门」总览页" aria-label="Permalink to &quot;1.1 PC 端缺「入门」总览页&quot;">​</a></h3><ul><li><strong>问题</strong>：现有 10 篇直接从技术栈开始，默认读者已在 Keystone 上下文中；无平台定位、项目族谱、术语表。原需求七板块中的「入门」实际无对应文档。</li><li><strong>影响</strong>：新人对「20+ 客户副本是什么关系」「该 clone 哪个仓库」无从下手，只能口口相传。</li><li><strong>建议</strong>：新建 <code>pc/introduction.md</code>（需求见需求文档 §4.1），作为每端入门页的固定结构样板。</li></ul><h3 id="_1-2-提交规范只有分支表-缺-commit-message-格式" tabindex="-1">1.2 提交规范只有分支表，缺 commit message 格式 <a class="header-anchor" href="#_1-2-提交规范只有分支表-缺-commit-message-格式" aria-label="Permalink to &quot;1.2 提交规范只有分支表，缺 commit message 格式&quot;">​</a></h3><ul><li><strong>问题</strong>：<code>guide/commit-specification.md</code> 仅 19 行分支命名表；而 <code>e9-delivery-ui</code> 实际已配 commitlint + commitizen（cz-customizable，<code>pnpm commit</code>），规则成文于配置而非文档。</li><li><strong>影响</strong>：规范「存在但不可见」：其他项目（e9-inspection-web 无任何 husky/commitlint）无法照搬；新人不知道有 <code>pnpm commit</code>，直接 git commit 会被 husky 拦截且不知所措。</li><li><strong>建议</strong>：按需求文档 §4.6 补全 message 格式篇，并以 e9-delivery-ui 的 commitlint 配置为唯一标准。</li></ul><h3 id="_1-3-技术栈、功能开发两篇过浅-撑不起「七板块」门面" tabindex="-1">1.3 技术栈、功能开发两篇过浅，撑不起「七板块」门面 <a class="header-anchor" href="#_1-3-技术栈、功能开发两篇过浅-撑不起「七板块」门面" aria-label="Permalink to &quot;1.3 技术栈、功能开发两篇过浅，撑不起「七板块」门面&quot;">​</a></h3><ul><li><strong>问题</strong>：技术栈 26 行纯链接清单；功能开发正文 31 行，实质内容全靠 <code>templates/*.vue</code> 代码内嵌，api 层写法、hooks、组件放置约定均无。</li><li><strong>影响</strong>：「功能开发」是使用频率最高的篇目，现状无法支撑新人独立开发第一个页面。</li><li><strong>建议</strong>：需求文档 §4.2 / §4.5 已定充实方案；templates 三模板继续作为代码样例，正文补讲解。</li></ul><h3 id="_1-4-代码模板仅覆盖-pc-arco-栈-移动端无模板" tabindex="-1">1.4 代码模板仅覆盖 PC Arco 栈，移动端无模板 <a class="header-anchor" href="#_1-4-代码模板仅覆盖-pc-arco-栈-移动端无模板" aria-label="Permalink to &quot;1.4 代码模板仅覆盖 PC Arco 栈，移动端无模板&quot;">​</a></h3><ul><li><strong>问题</strong>：<code>docs/templates/</code> 三个模板（list/edit/details）全是 Arco + PC 业务组件风格；移动端（uni-app + uView）无任何模板。</li><li><strong>影响</strong>：移动端「功能开发」篇落地时无样板可引，各客户项目页面风格继续发散。</li><li><strong>建议</strong>：templates 按端分目录（需求文档 §7.4）；移动端模板从 delivery-template-uniapp 真实业务页抽取，作为移动端功能开发篇的配套交付物，<strong>需与 5.5 同步立项</strong>。</li></ul><h3 id="_1-5-权限-i18n-深度文档「pc-独有」-移动端对应文档滞留项目内" tabindex="-1">1.5 权限 / i18n 深度文档「PC 独有」，移动端对应文档滞留项目内 <a class="header-anchor" href="#_1-5-权限-i18n-深度文档「pc-独有」-移动端对应文档滞留项目内" aria-label="Permalink to &quot;1.5 权限 / i18n 深度文档「PC 独有」，移动端对应文档滞留项目内&quot;">​</a></h3><ul><li><strong>问题</strong>：站点深度的按钮权限、i18n 系列只写了 PC；移动端其实有同主题文档（<code>delivery-template-uniapp/docs/uniapp-button-permission-rule-guide.md</code> 等 6 篇）但躺在项目仓库里未入站。</li><li><strong>影响</strong>：指南「三端对称」目标落空；移动端知识依赖「知道有那个仓库」这个隐性前提。</li><li><strong>建议</strong>：按需求文档 §5.6 / §5.7 迁入移动端规范与参考板块；迁移后按 SSOT 原则处理项目内副本（见 2.1）。</li></ul><h2 id="二、技术设施类缺口" tabindex="-1">二、技术设施类缺口 <a class="header-anchor" href="#二、技术设施类缺口" aria-label="Permalink to &quot;二、技术设施类缺口&quot;">​</a></h2><h3 id="_2-1-移动端工程无提交规范强制设施" tabindex="-1">2.1 移动端工程无提交规范强制设施 <a class="header-anchor" href="#_2-1-移动端工程无提交规范强制设施" aria-label="Permalink to &quot;2.1 移动端工程无提交规范强制设施&quot;">​</a></h3><ul><li><strong>问题</strong>：delivery-template-uniapp 无 husky、commitlint、eslint 配置；e9-inspection-web 同样裸奔。</li><li><strong>影响</strong>：PC 端成文的提交规范在移动端<strong>无法落地</strong>（指南写了也执行不了）；移动端代码风格无门禁。</li><li><strong>建议</strong>：短期在移动端提交规范篇注明「靠自觉 + MR 评审」；中期给模板工程补 husky + lint-staged + commitlint（与 PC 同配置），随模板派生自然铺开。</li></ul><h3 id="_2-2-指南站无部署-ci-且部署目标是「双份」的" tabindex="-1">2.2 指南站无部署 CI，且部署目标是「双份」的 <a class="header-anchor" href="#_2-2-指南站无部署-ci-且部署目标是「双份」的" aria-label="Permalink to &quot;2.2 指南站无部署 CI，且部署目标是「双份」的&quot;">​</a></h3><ul><li><strong>问题</strong>：部署靠手动构建 → 复制产物到 <code>docs/dist/E9-Front-Dev-Guide.io</code>（嵌套 git 仓库，指向 GitHub Pages）→ push；<code>.gitee/</code> 无任何 CI 配置，config.mts 注释却写 Gitee Pages。两个部署目标并存且无自动化。</li><li><strong>影响</strong>：发版步骤不可复现、易漏易错；嵌套 git 仓库在主仓库里以 gitlink 形式存在，克隆体验差；两处线上地址可能版本不一致。</li><li><strong>建议</strong>：二选一定主部署源（团队在 Gitee，建议 Gitee Pages 为主），淘汰嵌套仓库；补一条 CI（Gitee Go 或 GitHub Actions）：push master → build → deploy。</li></ul><h3 id="_2-3-node-包管理器版本约束普遍缺失" tabindex="-1">2.3 Node / 包管理器版本约束普遍缺失 <a class="header-anchor" href="#_2-3-node-包管理器版本约束普遍缺失" aria-label="Permalink to &quot;2.3 Node / 包管理器版本约束普遍缺失&quot;">​</a></h3><ul><li><strong>问题</strong>：除文档站（pnpm 10.19.0）与 beam-web（node &gt;=8.9，形同虚设）外，各项目 package.json 均无 engines 字段；e9-terminal-web 甚至把 pnpm 当依赖安装。</li><li><strong>影响</strong>：文档站要求 Node 24，而存量项目按老文档可能用 Node 14/16——新人环境错配产生的报错（node-sass、openssl 等）排查成本高。</li><li><strong>建议</strong>：各篇「快速开始」写明确切验证过的版本；有条件时给各项目补 engines + <code>preinstall</code> 检查；指南站首页给出「每端 Node/pnpm 版本速查表」。</li></ul><h3 id="_2-4-站点搜索仅中文-locale-配置" tabindex="-1">2.4 站点搜索仅中文 locale 配置 <a class="header-anchor" href="#_2-4-站点搜索仅中文-locale-配置" aria-label="Permalink to &quot;2.4 站点搜索仅中文 locale 配置&quot;">​</a></h3><ul><li><strong>问题</strong>：local search 只在中文 locale 下配置了翻译文案，英文侧无搜索。</li><li><strong>影响</strong>：英文读者体验残缺（结合 3.1 的双语策略调整，此项优先级可降低）。</li><li><strong>建议</strong>：随双语策略一并处理：若英文仅保留核心篇，则为英文 locale 补同款搜索配置即可。</li></ul><h2 id="三、工程管理类缺口" tabindex="-1">三、工程管理类缺口 <a class="header-anchor" href="#三、工程管理类缺口" aria-label="Permalink to &quot;三、工程管理类缺口&quot;">​</a></h2><h3 id="_3-1-三处文档副本同源不同步-最关键的结构性风险" tabindex="-1">3.1 三处文档副本同源不同步（最关键的结构性风险） <a class="header-anchor" href="#_3-1-三处文档副本同源不同步-最关键的结构性风险" aria-label="Permalink to &quot;3.1 三处文档副本同源不同步（最关键的结构性风险）&quot;">​</a></h3><ul><li><strong>问题</strong>：同一套指南内容存在于三处：本站 <code>docs/guide/</code>、<code>e9tech/keystone-deliver-ui/docs/</code>、<code>weChat-applet/delivery-template-uniapp/docs/</code>，且 keystone 仓库内的版本与站点版本已开始各自演化。</li><li><strong>影响</strong>：任何一处更新都会造成另两处过期；读者不知哪份是权威；AI 辅助编码（各项目 CLAUDE.md / skills 引用这些文档）可能读到旧规则。</li><li><strong>建议</strong>：确立<strong>站点为 SSOT</strong>（需求文档 §8.1）：项目内 docs 发布迁移后改为链接或删除；过渡期在项目内副本头部加「已迁移，以站点为准」横幅。</li></ul><h3 id="_3-2-移动端项目派生方式粗放" tabindex="-1">3.2 移动端项目派生方式粗放 <a class="header-anchor" href="#_3-2-移动端项目派生方式粗放" aria-label="Permalink to &quot;3.2 移动端项目派生方式粗放&quot;">​</a></h3><ul><li><strong>问题</strong>：移动端新项目靠「复制整个目录」派生，工作区里已出现：<code>delivery-template-uniapp - 副本</code>（整目录复制）、<code>delivery-template-uniapp.zip</code>（207MB 归档）、<code>查询当前文件夹的git地址.bat</code> 等痕迹；客户项目（changjin 等）与模板的关系无记录。</li><li><strong>影响</strong>：模板升级无法回灌到已派生项目；磁盘与仓库噪声大；「哪个是权威模板」全靠记忆；207MB 的 zip 若入库是事故。</li><li><strong>建议</strong>：模板仓库化——delivery-template-uniapp 独立 git 仓库 + 打 tag；派生项目走「clone 模板 → 改 remote → 记录基线 tag」流程；工作区清理副本与 zip（移入归档盘）；PC 端 20+ 客户副本同理核查派生记录。</li></ul><h3 id="_3-3-废弃-无关项目会误导读者" tabindex="-1">3.3 废弃 / 无关项目会误导读者 <a class="header-anchor" href="#_3-3-废弃-无关项目会误导读者" aria-label="Permalink to &quot;3.3 废弃 / 无关项目会误导读者&quot;">​</a></h3><ul><li><strong>问题</strong>：<code>admin-app/e9ech</code> 是 e9tech 的残缺拷贝（无配置无 git）却与 e9tech 仅一字母之差；<code>admin-app/uniapp-admin</code> 是未定制的 DCloud 官方模板，与真实移动端栈（uni-app Vue2 + uView）无关。</li><li><strong>影响</strong>：读者（及 AI 辅助编码）把废弃目录当代码蓝本，得出错误结论。</li><li><strong>建议</strong>：入门页项目族谱表标注状态（需求文档 §4.1 已含）；有条件时将废弃目录移出工作区或改名（如 <code>_archived/</code> 前缀）。</li></ul><h3 id="_3-4-移动端无-pages-json-生成-裁剪脚本-全量分包交付" tabindex="-1">3.4 移动端无 pages.json 生成 / 裁剪脚本，全量分包交付 <a class="header-anchor" href="#_3-4-移动端无-pages-json-生成-裁剪脚本-全量分包交付" aria-label="Permalink to &quot;3.4 移动端无 pages.json 生成 / 裁剪脚本，全量分包交付&quot;">​</a></h3><ul><li><strong>问题</strong>：PC 端多客户靠 <code>VITE_BUILD_VIEWS</code> 编译期裁剪；移动端页面<strong>全量打进分包</strong>，客户差异完全交给运行时权限与 prefix-rules。</li><li><strong>影响</strong>：这是现状机制而非缺陷，但意味着：小程序包体积随业务只增不减（主包 2MB 红线风险）；客户 A 的页面代码对客户 B 可见（若涉及敏感逻辑需注意）。</li><li><strong>建议</strong>：项目结构篇如实记录该机制及体积红线；将「分包体积监控」列入移动端遗留项；如未来需要编译期裁剪再评估脚本方案。</li></ul><h2 id="四、流程类缺口" tabindex="-1">四、流程类缺口 <a class="header-anchor" href="#四、流程类缺口" aria-label="Permalink to &quot;四、流程类缺口&quot;">​</a></h2><h3 id="_4-1-双语镜像维护不可持续" tabindex="-1">4.1 双语镜像维护不可持续 <a class="header-anchor" href="#_4-1-双语镜像维护不可持续" aria-label="Permalink to &quot;4.1 双语镜像维护不可持续&quot;">​</a></h3><ul><li><strong>问题</strong>：现状 10 篇 ×2 语言已靠一次性补齐；三端目标 21+ 篇，若每篇都维护英文镜像，翻译工作量翻倍且必然滞后。</li><li><strong>影响</strong>：英文版长期过期比没有更糟（读者无法分辨新旧）。</li><li><strong>建议</strong>：中文先行、英文仅核心篇 + 「以中文为准」提示（需求文档 §7.2 已定）；现有英文镜像在对应中文篇大改时同步更新或降级。</li></ul><h3 id="_4-2-无内容-owner-评审-过期机制" tabindex="-1">4.2 无内容 owner / 评审 / 过期机制 <a class="header-anchor" href="#_4-2-无内容-owner-评审-过期机制" aria-label="Permalink to &quot;4.2 无内容 owner / 评审 / 过期机制&quot;">​</a></h3><ul><li><strong>问题</strong>：指南无元信息（负责人、最后验证日期），无评审流，git 历史全为「首次提交」无追溯价值。</li><li><strong>影响</strong>：文档腐化不可见——没人知道某篇是否还与代码一致；新人按过期文档操作踩坑后对指南失去信任。</li><li><strong>建议</strong>：需求文档 §8.3/§8.4 已定元信息与 MR 评审机制；另建议 git 提交遵循同一套 commit 规范（指南站自己先用起来）。</li></ul><h3 id="_4-3-三端技术栈代际割裂-升级无规划" tabindex="-1">4.3 三端技术栈代际割裂，升级无规划 <a class="header-anchor" href="#_4-3-三端技术栈代际割裂-升级无规划" aria-label="Permalink to &quot;4.3 三端技术栈代际割裂，升级无规划&quot;">​</a></h3><ul><li><strong>问题</strong>：PC 主力 Vue3 + Arco / Vite4；移动端 uni-app <strong>Vue2</strong> + HBuilderX（工具链与 PC 完全不同）；桌面端 Electron 29 + Vue 2.7（且 Vue2.7 是过渡版本）；存量 PC 还有两套 Vue2 栈。HBuilderX 工程化程度低（无 CLI、依赖管理弱），与 PC 的 pnpm 工作流割裂。</li><li><strong>影响</strong>：跨端协作成本高；uni-app Vue2 生态在收缩（官方已主推 Vue3/CLI），长期有工具链停更风险；桌面端基于 Vue2.7 新功能开发空间受限。</li><li><strong>建议</strong>：本期按已确认决策<strong>如实记录现状</strong>，不按目标态虚构；将「uni-app 迁移 Vue3 + CLI 化」「Electron 升级与前端框架选型」列为独立遗留项，待业务空窗期立项，不在指南内承诺时间表。</li></ul><h2 id="结论摘要" tabindex="-1">结论摘要 <a class="header-anchor" href="#结论摘要" aria-label="Permalink to &quot;结论摘要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>事项</th></tr></thead><tbody><tr><td>高（阻塞指南三端化落地）</td><td>1.1 PC 入门页 · 1.2 提交规范补全 · 1.5 移动端文档迁入 · 3.1 确立 SSOT</td></tr><tr><td>中（影响可用性）</td><td>1.3 技术栈/功能开发充实 · 2.2 部署 CI · 2.3 版本速查 · 4.1 双语策略</td></tr><tr><td>低（记录在案、择机处理）</td><td>2.1 移动端规范设施 · 3.2 模板仓库化 · 3.3 废弃目录清理 · 3.4 分包体积监控 · 4.2 owner 机制 · 4.3 三端升级规划</td></tr></tbody></table>',40)])])}const m=t(l,[["render",r]]);export{h as __pageData,m as default};
